import{bt as e,ct as t,lt as n,n as r,ot as i,rt as a,st as o,wt as s}from"./chunks/framework.CcbqhlXh.js";var c=JSON.parse(`{"title":"Bundling and Tree-Shaking","description":"","frontmatter":{},"headers":[],"relativePath":"tree-shaking.md","filePath":"tree-shaking.md","lastUpdated":1794949754000}`),l={name:`tree-shaking.md`};function u(r,c,l,u,d,f){let p=s(`CopyOrDownloadAsMarkdownButtons`);return e(),i(`div`,null,[c[0]||=a(`h1`,{id:`bundling-and-tree-shaking`,tabindex:`-1`},[t(`Bundling and Tree-Shaking `),a(`a`,{class:`header-anchor`,href:`#bundling-and-tree-shaking`,"aria-label":`Permalink to “Bundling and Tree-Shaking”`},`​`)],-1),n(p),c[1]||=o(`<p>What the <code>@tolki</code> packages promise your bundler, and the few cases where you add a <code>/* @__PURE__ */</code> comment yourself.</p><p>The results below were measured on Rollup 4.68.5, Rolldown 1.3.2 (Vite 8), esbuild 0.28.2, webpack 5.112.2 and Rspack 2.3.3, against the published form of each package. The repository&#39;s <code>pnpm treeshake:check</code> repeats the measurements and fails when a bundler changes an outcome, so this page is updated with it.</p><h2 id="what-the-packages-guarantee" tabindex="-1">What the packages guarantee <a class="header-anchor" href="#what-the-packages-guarantee" aria-label="Permalink to “What the packages guarantee”">​</a></h2><ul><li><strong>Unused imports leave your bundle.</strong> Every package sets <code>&quot;sideEffects&quot;: false</code>, and named imports shake in all five bundlers. </li><li><strong>Unused calls leave too.</strong> A function with no side effects carries <code>/* @__NO_SIDE_EFFECTS__ */</code>. Rollup, Rolldown, webpack and Rspack then drop a call whose result nothing uses, including a call at the top level of a module. </li><li><strong>Importing a package runs no setup code.</strong> The packages&#39; own module-level calls are marked <code>/* @__PURE__ */</code>, so a bundler drops them when nothing uses them, esbuild included. </li><li><strong>Functions with effects are always kept.</strong> A function that changes what you pass, writes module state, runs a callback for its effects or exists to throw has no annotation, so a call to it stays. Each package page names its own, such as <code>pop</code> and <code>shift</code> in <a href="/arrays-objects/#bundling">Arrays &amp; Objects</a> and <code>useLocale</code> in <a href="/numbers/#bundling">Numbers</a>. </li></ul><h2 id="namespace-imports" tabindex="-1">Namespace imports <a class="header-anchor" href="#namespace-imports" aria-label="Permalink to “Namespace imports”">​</a></h2><p>A namespace import shakes exactly like named imports when you read its members by name:</p><div class="language-typescript" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> *</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> as</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Str </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;@tolki/str&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> title</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Str.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">after</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(input, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;:&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>Only <code>Str.after</code> and what it needs end up in the bundle. The same holds for <code>@tolki/arr</code>, <code>@tolki/num</code> and the other packages.</p><p>Two uses keep the whole package, because the bundler can no longer tell which members you need:</p><ul><li>passing the namespace object around, as in <code>register(Str)</code>;</li><li>reading a computed member, as in <code>Str[name]</code>.</li></ul><h2 id="per-bundler" tabindex="-1">Per bundler <a class="header-anchor" href="#per-bundler" aria-label="Permalink to “Per bundler”">​</a></h2><div class="table-scroll"><table tabindex="0"><thead><tr><th>Bundler</th><th>An unused call to a helper</th><th>What you do</th></tr></thead><tbody><tr><td>Rollup</td><td>Dropped, and nothing is left behind.</td><td>Nothing.</td></tr><tr><td>Rolldown (Vite 8)</td><td>Dropped. For the helpers in <a href="#dependency-residue">Dependency residue</a>, the code behind them can stay. In the generated route shape, the curried helpers are kept (see below).</td><td>Nothing for helpers. <code>/* @__PURE__ */</code> for the <a href="#generated-enums-and-routes">curried routes</a>, and on the dependency-residue calls.</td></tr><tr><td>esbuild</td><td>Kept. esbuild never follows <code>/* @__NO_SIDE_EFFECTS__ */</code> from one file to another.</td><td>Write <code>/* @__PURE__ */ fn(...)</code> on every call you want removed.</td></tr><tr><td>webpack</td><td>Dropped, and nothing is left behind. In the generated route shape, the curried helpers are kept (see below).</td><td>Nothing for helpers. <code>/* @__PURE__ */</code> for the <a href="#generated-enums-and-routes">curried routes</a>.</td></tr><tr><td>Rspack</td><td>Dropped. A few helpers leave code behind (see <a href="#dependency-residue">Dependency residue</a>), and so does an enum file that derives a list.</td><td>Nothing, or <code>/* @__PURE__ */</code> on those calls.</td></tr></tbody></table></div><p>&quot;Dropped&quot; means the bundle came out byte-identical to one without the call. </p><h2 id="when-to-write-pure" tabindex="-1">When to write <code>/* @__PURE__ */</code> <a class="header-anchor" href="#when-to-write-pure" aria-label="Permalink to “When to write /* @__PURE__ */”">​</a></h2><p>Put the comment right before the call, on the call itself and on each call nested in its arguments:</p><div class="language-typescript" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> id</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"> /* @__PURE__ */</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> uuid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><p>You need it in these cases:</p><ul><li><strong>esbuild.</strong> It drops the call only with the comment. With it, an unused call drops in all five bundlers. </li><li><strong>Generated routes with a curried helper.</strong> See below.</li><li><strong>A class.</strong> <code>new Collection(...)</code>, <code>new Translator(...)</code> and <code>new Stringable(...)</code> can stay in the bundle without it, because a bundler cannot mark a constructor. A call-site <code>/* @__PURE__ */ new Collection(...)</code> drops them in every bundler.</li><li><strong>A helper that leaves dependency code behind</strong> in Rolldown or Rspack. See below.</li></ul><h2 id="dependency-residue" tabindex="-1">Dependency residue <a class="header-anchor" href="#dependency-residue" aria-label="Permalink to “Dependency residue”">​</a></h2><p>In Rolldown and Rspack, an unused top-level call to one of these helpers drops the call but can keep the code of the package behind it. Writing <code>/* @__PURE__ */</code> before the call drops everything. </p><p>The cause is how the packages are published: Rolldown honours <code>/* @__NO_SIDE_EFFECTS__ */</code> across files only on a function exported inline (<code>export function f</code>), and the published files use export lists. So the call goes, and the dependency of the helper&#39;s module stays.</p><div class="table-scroll"><table tabindex="0"><thead><tr><th>Helpers</th><th>What can stay behind</th></tr></thead><tbody><tr><td><code>uuid</code>, <code>uuid7</code></td><td>the <code>uuid</code> package</td></tr><tr><td><code>ulid</code></td><td>the <code>ulid</code> package</td></tr><tr><td><code>plural</code>, <code>singular</code>, <code>counted</code>, <code>isPlural</code>, <code>isSingular</code>, <code>pluralStudly</code>, <code>pluralPascal</code>, <code>matchCase</code>, <code>uncountable</code></td><td><code>pluralize</code></td></tr><tr><td><code>markdown</code>, <code>inlineMarkdown</code>, <code>markDownRenderer</code></td><td><code>markdown-it</code></td></tr><tr><td><code>slug</code>, <code>ascii</code></td><td><code>transliteration</code></td></tr><tr><td><code>str</code>, <code>of</code></td><td>the whole <code>Stringable</code> class and its dependencies</td></tr><tr><td><code>collect</code></td><td>the <code>Collection</code> class and its helpers</td></tr></tbody></table></div><p>Rspack alone has two more:</p><ul><li><strong><code>createLang</code></strong> (<code>@tolki/lang</code> and <code>@tolki/lang/vue</code>) leaves dead <code>@tolki/utils</code> code under Rspack&#39;s default minifier settings. SWC <code>compress.passes: 3</code> in <code>optimization.minimizer</code> removes it. </li><li><strong><code>spell</code> and <code>spellOrdinal</code></strong> (<code>@tolki/num</code>) keep the chunk-loading runtime for the dynamic <code>import()</code> of their locale files. </li></ul><p>Rollup and webpack drop all of these cleanly.</p><h2 id="large-dependencies" tabindex="-1">Large dependencies <a class="header-anchor" href="#large-dependencies" aria-label="Permalink to “Large dependencies”">​</a></h2><p>Some imports are big on their own, and no bundler setting changes that, because the code is used when you call them:</p><ul><li><strong><code>slug</code> and <code>ascii</code></strong> carry <code>transliteration</code>, which holds the character tables for every script. Import them only where you need them. </li><li><strong><code>markdown</code>, <code>inlineMarkdown</code> and <code>markDownRenderer</code></strong> carry <code>markdown-it</code>.</li><li><strong><code>str</code> and <code>of</code></strong> return a <code>Stringable</code>, a class with every string helper as a method, so a bundle that uses either keeps the whole class and every dependency it uses. For small bundles, import the string functions one by one instead. </li><li><strong><code>collect</code> and <code>new Collection</code></strong> keep the whole <code>Collection</code> class.</li></ul><h2 id="generated-enums-and-routes" tabindex="-1">Generated enums and routes <a class="header-anchor" href="#generated-enums-and-routes" aria-label="Permalink to “Generated enums and routes”">​</a></h2><p>A file generated by the TypeScript publisher is a module-level call such as <code>export const Status = defineEnum({...})</code>. Whether an unused one drops depends on the shape and on the bundler:</p><div class="table-scroll"><table tabindex="0"><thead><tr><th>Generated shape</th><th>Rollup</th><th>Rolldown</th><th>esbuild</th><th>webpack</th><th>Rspack</th></tr></thead><tbody><tr><td>An enum alone, or a plain <code>defineRoute({...})</code></td><td>dropped</td><td>dropped</td><td>kept</td><td>dropped</td><td>dropped</td></tr><tr><td>An enum file that also derives a list, as in <code>values(Status)</code></td><td>dropped</td><td>dropped</td><td>kept</td><td>dropped</td><td>kept</td></tr><tr><td>A curried route, <code>annotatePageProps&lt;T&gt;()(defineRoute({...}))</code> or <code>annotateRequestPayload&lt;T&gt;()(defineRoute({...}))</code></td><td>dropped</td><td>kept</td><td>kept</td><td>kept</td><td>dropped</td></tr><tr><td>Any of the above with <code>/* @__PURE__ */</code> on each call</td><td>dropped</td><td>dropped</td><td>dropped</td><td>dropped</td><td>dropped</td></tr></tbody></table></div><p>For a curried route, write the comment on the outer call and on the inner <code>defineRoute</code>:</p><div class="language-typescript" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> show</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"> /* @__PURE__ */</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> annotatePageProps</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ShowProps</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;()(</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  /* @__PURE__ */</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> defineRoute</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ url: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/users/{user}&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, methods: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;get&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] }),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>The <a href="/ts/enums.html#bundling">Enums</a> and <a href="/ts/routing.html#bundling">Routing</a> pages show the same notes beside the generated code.</p><h2 id="where-to-read-more" tabindex="-1">Where to read more <a class="header-anchor" href="#where-to-read-more" aria-label="Permalink to “Where to read more”">​</a></h2><p>Each package page has a short Bundling section with its own exceptions:</p><ul><li><a href="/strings/#bundling">Strings</a></li><li><a href="/numbers/#bundling">Numbers</a></li><li><a href="/arrays-objects/#bundling">Arrays &amp; Objects</a></li><li><a href="/collections/#bundling">Collections</a></li><li><a href="/localization/#bundling">Localization</a></li><li><a href="/ts/enums.html#bundling">Enums</a></li><li><a href="/ts/routing.html#bundling">Routing</a></li></ul>`,37)])}var d=r(l,[[`render`,u]]);export{c as __pageData,d as default};